import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// n lines, each one unit at `price`.
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

// Issue #12: the customer discount must be applied exactly once.
test('customer discount is applied once (under 10 lines)', () => {
  // 1,000 less 10% = 900
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('bulk discount is applied once, after the customer discount (10 lines)', () => {
  // 10,000 less 10% = 9,000, then less 5% = 8,550
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('no bulk discount on 9 lines with a customer discount', () => {
  // 9,000 less 10% = 8,100
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

// Issue #12: totals at discount rate 0 must stay as they were before the fix.
test('totals at discount rate 0 are unchanged', () => {
  assert.equal(total(lines(9, 1000), 0), 9000); // no discount at all
  assert.equal(total(lines(10, 1000), 0), 9500); // 5% bulk only
  assert.equal(total(lines(10, 33), 0), 314); // 330 less 5% = 313.5, rounded
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
